// What each stage is for: who is in it, the key activities, the feature that
// serves each activity, what the menu shows and locks, the emails they get, and
// the words we use to market it. One source for the docs
// (docs/CANDIDATE_STAGES.md, generated by `npm run docs:stages`), the public
// "How it works" page, and the tests that keep it honest against the real menu.

import type { JourneyStage } from './journey'
import { getStage } from './journey'
import { MENU_LABELS, MENU_RULES, itemVisibility, menuMode, type MenuItemKey, type MenuMode } from './menu'

export type GuideStage = Exclude<JourneyStage, 'PAUSED'>

export type Activity = { activity: string; feature: MenuItemKey }

export type StageGuide = {
  stage: GuideStage
  who: string
  marketing: { headline: string; body: string }
  activities: Activity[]
  emails: string[]
  // How the pace changes when someone is looking casually rather than actively.
  casualNote: string | null
}

