const MODE_OF: Record<GuideStage, MenuMode> = {
  EXPLORING: 'EXPLORING',
  PREPARING: 'PREPARING',
  APPLYING: 'ACTIVE',
  INTERVIEWING: 'ACTIVE',
  OFFER: 'ACTIVE',
  LANDED: 'LANDED',
  STAYING: 'STAYING',
}

// What the menu does in this stage, from the same rules the sidebar uses.
export function menuFor(stage: GuideStage): { shown: string[]; locked: string[] } {
  const mode = menuMode(stage)
  const keys = Object.keys(MENU_RULES) as MenuItemKey[]
  const label = (k: MenuItemKey) => MENU_LABELS[k]
  return {
    shown: keys.filter((k) => itemVisibility(k, mode) === 'show').map(label),
    locked: keys.filter((k) => itemVisibility(k, mode) === 'locked').map(label),
  }
}

export function stageName(stage: GuideStage): string {
  return getStage(stage).label
}

export function stageDescription(stage: GuideStage): string {
  return getStage(stage).plan
}

export { MODE_OF }
